][1][5] = {}tAnniversaryCelebration_GiftData[3100085][1][5]["RandomItemChanceType"] = 2tAnniversaryCelebration_GiftData[3100085][1][5]["ItemChance"] = 100tAnniversaryCelebration_GiftData[3100085][1][5]["Item_1"] = 5tAnniversaryCelebration_GiftData[3100085][1][5]["ItemId"] = 3100088tAnniversaryCelebration_GiftData[3100085][1][5]["GetNum"] = 1tAnniversaryCelebration_GiftData[3100085][1][5]["Tips"] = tAnniversaryCelebration_Text[3100085][5]tAnniversaryCelebration_GiftData[3100085][1][6] = {}tAnniversaryCelebration_GiftData[3100085][1][6]["RandomItemChanceType"] = 2tAnniversaryCelebration_GiftData[3100085][1][6]["ItemChance"] = 100tAnniversaryCelebration_GiftData[3100085][1][6]["Item_1"] = 6tAnniversaryCelebration_GiftData[3100085][1][6]["ItemId"] = 3100089tAnniversaryCelebration_GiftData[3100085][1][6]["GetNum"] = 1tAnniversaryCelebration_GiftData[3100085][1][6]["Tips"] = tAnniversaryCelebration_Text[3100085][6]--天石包tAnniversaryCelebration_GiftData[3100086] = {}tAnniversaryCelebration_GiftData[3100086]["Type"] = "CP"tAnniversaryCelebration_GiftData[3100086]["Amount"] = 2000 tAnniversaryCelebration_GiftData[3100087] = {}tAnniversaryCelebration_GiftData[3100087]["Type"] = "CPMono"tAnniversaryCelebration_GiftData[3100087]["Amount"] = 2000tAnniversaryCelebration_GiftData[3100088] = {}tAnniversaryCelebration_GiftData[3100088]["Type"] = "CP"tAnniversaryCelebration_GiftData[3100088]["Amount"] = 4000tAnniversaryCelebration_GiftData[3100089] = {}tAnniversaryCelebration_GiftData[3100089]["Type"] = "CPMono"tAnniversaryCelebration_GiftData[3100089]["Amount"] = 4000   ------------------------------------------逻辑部分------------------------------------------天石包function AnniversaryCelebration_CPPack(nItemId)	local sType = tAnniversaryCelebration_GiftData[nItemId]["Type"]	local nAmount = tAnniversaryCelebration_GiftData[nItemId]["Amount"]	if sType == "CP" then		if (Get_UserEMoney()+nAmount >= G_User_MaxEmoney) then			Sys_MsgBox(tAnniversaryCelebration_Text["Msg"]["CPLimit"])			return		end		if (Item_ChkItem(nItemId) and Item_DelItem(nItemId)) then			User_AddEMoney(nAmount)			Sys_SaveActionFestivalLog(string.format(tAnniversaryCelebration_Log["CP"],nItemId,nAmount))			Sys_MsgBox(string.format(tAnniversaryCelebration_Text["Msg"]["GetCP"],nAmount))			return		end	elseif sType == "CPMono" then		if (Get_UserMonoEMoney()+nAmount >= G_User_MaxEmoneyMono) then			Sys_MsgBox(tAnniversaryCelebration_Text["Msg"]["CPMonoLimit"])			return		end		if (Item_ChkItem(nItemId) and Item_DelItem(nItemId)) then			User_AddEMoneyMono(nAmount)			Sys_SaveActionFestivalLog(string.format(tAnniversaryCelebration_Log["CPMono"],nItemId,nAmount))			Sys_MsgBox(string.format(tAnniversaryCelebration_Text["Msg"]["GetCPMono"],nAmount))			return		end			endend--礼包打开function AnniversaryCelebration_SignPack(nItemId)	--过期删除	if not AnniversaryCelebration_ActivityTimeChk(nItemId) then		return	end	--检查掩码, 隔天	local nEvent =tAnniversaryCelebration_Stc["EventData"]	local nType = tAnniversaryCelebration_Stc["TypeData"]["OpenTime"]	local nNowTime = Get_UserStatisticValue(nEvent,nType) or 0		if nNowTime > 0 then 		if not Task_StcInterval(nEvent,nType,1,4) then			local sTip = string.format(tAnniversaryCelebration_Text["Msg"]["Interval"],Get_ItemtypeName(nItemId))			Sys_MsgBox(sTip)			return		end	end	nNowTime = nNowTime+1	--空间不足	local nSpace = tAnniversaryCelebration_GiftData[nItemId][nNowTime]["Space"]	if not User_CheckLeftSpace(nSpace) then		local sTip = string.format(tAnniversaryCelebration_Text["Msg"]["NoSpace"],nSpace)		Sys_MsgBox(sTip)		return			end		--删除礼包	if nNowTime >= tAnniversaryCelebration_Stc["OpenMaxTime"] then		if not (Item_ChkItem(nItemId) and Item_DelItem(nItemId)) then			return		end	end	--打时间戳，获得奖励	Task_SetStatistic(nEvent,nType,nNowTime,1) 	Task_SetStcTimestamp(nEvent,nType,0) 	AnniversaryCelebration_SignAward(nItemId,nNowTime)	User_EffectAdd("self",tAnniversaryCelebration_Cont["Effect"])end	function AnniversaryCelebration_SignAward(nItemId,nNowTime)	local sTip = tAnniversaryCelebration_Text[nItemId][nNowTime]	local sLog = string.format(tAnniversaryCelebration_GiftData[nItemId][nNowTime]["Log"],nItemId,nNowTime)	for i,v in ipairs(tAnniversaryCelebration_GiftData[nItemId][nNowTime]["Award"]) do		Item_AddNewItem(v.ItemId,v.Attr)	end	Sys_SaveActionFestivalLog(sLog)	Sys_MsgBox(sTip)endfunction AnniversaryCelebration_ActivityTimeChk(nItemId)	--过期删除	if not Sys_ChkFullTime(tAnniversaryCelebration_Cont["ActivityTime"]) then		if Item_ChkItem(nItemId) then			local sLog = string.format(tAnniversaryCelebration_Log["OverTime"],nItemId)			local sStr = string.format(tAnniversaryCelebration_Text["Msg"]["OverTime"],Get_ItemtypeName(nItemId))			Item_DelItem(nItemId)			Sys_SaveActionFestivalLog(sLog)			User_TalkChannel2005(sStr)		end		return false		else		return true	endend--付费礼包第一层对白function AnniversaryCelebration_RandomPackDialogue1(nItemId)	--过期删除	if not AnniversaryCelebration_ActivityTimeChk(nItemId) then		return	end	Sys_DialogText(tAnniversaryCelebration_Text["DialogText1"][nItemId])	Sys_DialogOption(tAnniversaryCelebration_Text["DialogOption1"][nItemId],"</F>AnniversaryCelebration_RandomPackDialogue2</N>"..nItemId)	Sys_DialogEnd()	end--付费礼包二次确认function AnniversaryCelebration_RandomPackDialogue2(nItemId)	--过期删除	if not AnniversaryCelebration_ActivityTimeChk(nItemId) then		return	end	local sText2 = string.format(tAnniversaryCelebration_Text["DialogText2"],tAnniversaryCelebration_GiftData[nItemId]["CostCP"],Get_ItemtypeName(nItemId))	Sys_DialogText(sText2)	Sys_DialogOption(tAnniversaryCelebration_Text["DialogOption2"],"</F>AnniversaryCelebration_RandomPack</N>"..nItemId)	Sys_DialogEnd()		end	function AnniversaryCelebration_RandomPack(nItemId)	--过期删除	if not (AnniversaryCelebration_ActivityTimeChk(nItemId)) then		return	end	--检查天石	local nCostCP = tAnniversaryCelebration_GiftData[nItemId]["CostCP"]	if not (Get_UserEMoney() >= nCostCP) then		Sys_MsgBox(tAnniversaryCelebration_Text["Msg"]["NoCPs"])		return	end			--背包	local nSpace = tAnniversaryCelebration_GiftData[nItemId]["Space"]	if not User_CheckLeftSpace(nSpace) then		Sys_MsgBox(string.format(tAnniversaryCelebration_Text["Msg"]["NoSpace"],nSpace))		return	end		--扣除天石，删物品，给奖励	if User_AddEMoney(-nCostCP) then		AnniversaryCelebration_RandomAward(nItemId,nCostCP)		User_EffectAdd("self",tAnniversaryCelebration_Cont["Effect"])		AnniversaryCelebration_RandomPackDialogue1(nItemId)	end	endfunction AnniversaryCelebration_RandomAward(nItemId,nCostCP)	local flat,tTable = Probabil_RandomAward(tAnniversaryCelebration_GiftData[nItemId],1)	local nAwardItemId = tTable[1]["tAward"][1]["ItemId"]	local nGetNum = tTable[1]["tAward"][1]["GetNum"]	local sTips = string.format(tAnniversaryCelebration_Text["Msg"]["GetRandomAward"],tTable[1]["tAward"][1]["Tips"])	local sLog = string.format(tAnniversaryCelebration_Log["RandomAward"],nCostCP,nItemId,nAwardItemId,nGetNum)	Item_AddNewItem(nAwardItemId,"0 "..nGetNum)	AnniversaryCelebration_Broadcast(nAwardItemId)	Sys_SaveActionFestivalLog(sLog)	Sys_SaveEmoneyBuy(tAnniversaryCelebration_Log["Emoney"][nItemId])	Sys_MsgBox(sTips)end--function AnniversaryCelebration_Signup(nNpcId)	--活动过期	if not Sys_ChkFullTime(tAnniversaryCelebration_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"2-1")		return	end			--已领取	local nEvent =tAnniversaryCelebration_Stc["EventData"]	local nType = tAnniversaryCelebration_Stc["TypeData"]["SignUp"]	if Task_ChkStcValue(nEvent,nType,">=",tAnniversaryCelebration_Stc["SignUpMark"]) then		LinkNpcGossipFunc_New(nNpcId,"2-2")		return	end				--等级限制	if not User_JudgeLevelAndMetempsychosis(tAnniversaryCelebration_Cont["Level"],tAnniversaryCelebration_Cont["Metempsychosis"]) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end			--背包检查	if not User_CheckLeftSpace(tAnniversaryCelebration_Cont["Space"]) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end			--符合条件，打掩码，给礼包	local nMetempsychosis = Get_UserMetempsychosis()		if nMetempsychosis >= 2 then		nMetempsychosis = 2	end		local nSignItemId = tAnniversaryCelebration_Cont["SignUp"][nMetempsychosis]	local sTips = string.format(tAnniversaryCelebration_Text["Msg"]["SignUp"],Get_ItemtypeName(nSignItemId))	local sLog = string.format(tAnniversaryCelebration_Log["SignUp"],nSignItemId)	Task_SetStatistic(nEvent,nType,tAnniversaryCelebration_Stc["SignUpMark"],1) 	Task_SetStcTimestamp(nEvent,nType,0) 	Item_AddNewItem(nSignItemId,"")	Sys_MsgBox(sTips)	User_EffectAdd("self",tAnniversaryCelebration_Cont["Effect"])	Sys_SaveActionFestivalLog(sLog)	endfunction AnniversaryCelebration_Surprise(nNpcId,nCostCP)	--活动过期	if not Sys_ChkFullTime(tAnniversaryCelebration_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"2-1")		return	end			--背包检查	if not User_CheckLeftSpace(tAnniversaryCelebration_Cont["Space"]) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end			local nSurpriseItemId = tAnniversaryCelebration_Cont["Surprise"][nCostCP]	if Item_ChkItem(nSurpriseItemId) then		Sys_MsgBox(string.format(tAnniversaryCelebration_Text["Msg"]["Have"],Get_ItemtypeName(nSurpriseItemId)))		return	end	local sTips = string.format(tAnniversaryCelebration_Text["Msg"]["Surprise"],Get_ItemtypeName(nSurpriseItemId))	local sLog = string.format(tAnniversaryCelebration_Log["Surprise"],nSurpriseItemId)	Item_AddNewItem(nSurpriseItemId,"")	Sys_MsgBox(sTips)	User_EffectAdd("self",tAnniversaryCelebration_Cont["Effect"])	Sys_SaveActionFestivalLog(sLog)		for i,v in pairs(tAnniversaryCelebration_Cont["Surprise"]) do		if not (Item_ChkItem(v)) then			LinkNpcGossipFunc_New(nNpcId,"3-1")			return		end	endendfunction AnniversaryCelebration_Broadcast(ntemId)	for i,v in ipairs(tAnniversaryCelebration_Cont["BroadcastItem"]) do		if ntemId == v then 			local sContent = string.format(tAnniversaryCelebration_Text["Msg"]["Broadcast"],Get_UserName(),Get_ItemtypeName(ntemId),tAnniversaryCelebration_Text[ntemId])			Sys_SystemBroadcast(sContent)			return		end	endend--------------------------------------------物品模块-------------------------------------tNpcFace[4088] = 110tNpcGossip[11014] = tNpcGossip[11014] or DefaultNpc:new{}tNpcGossip[11014]["OptionHidden"] = 1--周年庆欢庆大使tNpcGossip[11014]["Text1-1"] = {111,112}tNpcGossip[11014]["tOption1-1"] = {111,112,113}tNpcGossip[11014]["Text111"] = tAnniversaryCelebration_Text[11014]["Text111"]tNpcGossip[11014]["Text112"] = tAnniversaryCelebration_Text[11014]["Text112"]tNpcGossip[11014]["Option111"] = tAnniversaryCelebration_Text[11014]["Option111"]tNpcGossip[11014]["Option112"] = tAnniversaryCelebration_Text[11014]["Option112"]tNpcGossip[11014]["Option113"] = tAnniversaryCelebration_Text[11014]["Option113"]tNpcGossip[11014]["OptionFunc111"] = "AnniversaryCelebration_Signup</N>11014"tNpcGossip[11014]["OptionPoint112"] = "3"tNpcGossip[11014]["ChkFunc1-1"] = function ()	return trueendtNpcGossip[11014]["OptionChkFunc111"] = function ()	return Sys_ChkFullTime(tAnniversaryCelebration_Cont["ActivityTime"])endtNpcGossip[11014]["OptionChkFunc112"] = function ()	return Sys_ChkFullTime(tAnniversaryCelebration_Cont["ActivityTime"])end--过期tNpcGossip[11014]["Text2-1"] = {211}tNpcGossip[11014]["tOption2-1"] = {211}tNpcGossip[11014]["Text211"] = tAnniversaryCelebration_Text[11014]["Text211"]tNpcGossip[11014]["Option211"] = tAnniversaryCelebration_Text[11014]["Option211"]--我要签到，失败，已签到tNpcGossip[11014]["Text2-2"] = {221}tNpcGossip[11014]["tOption2-2"] = {221}tNpcGossip[11014]["Text221"] = tAnniversaryCelebration_Text[11014]["Text221"]tNpcGossip[11014]["Option221"] = tAnniversaryCelebration_Text[11014]["Option221"]--等级不zutNpcGossip[11014]["Text2-3"] = {231}tNpcGossip[11014]["tOption2-3"] = {231}tNpcGossip[11014]["Text231"] = tAnniversaryCelebration_Text[11014]["Text231"]tNpcGossip[11014]["Option231"] = tAnniversaryCelebrat